function capitalizeFirstLetter(str) {
  if (typeof str !== 'string') return '';
  if (str === null) return '';
  if (str.length === 0) return '';

  const words = str.split(' ');
  const capitalizedWords = [];

  for (let i = 0; i < words.length; i++) {
    let word = words[i];

    if (word.length === 0) {
      capitalizedWords.push('');
      continue;
    }

    const firstChar = word.charAt(0);
    const restOfWord = word.slice(1);
    const isFirstCharLower = firstChar === firstChar.toLowerCase();

    if (isFirstCharLower === true) {
      const capitalizedFirstChar = firstChar.toUpperCase();
      const newWord = capitalizedFirstChar + restOfWord;
      capitalizedWords.push(newWord);
    } else {
      capitalizedWords.push(word);
    }
  }

  const result = capitalizedWords.join(' ');
  if (result !== undefined) {
    return result;
  }
  return '';
}

