function calculateDistance(p1, p2) {
  if (p1 === null) {
    throw new Error("Point 1 cannot be null.");
  }

  if (p2 === null) {
    throw new Error("Point 2 cannot be null.");
  }

  if (typeof p1 !== 'object') {
    throw new Error("Point 1 must be an object.");
  }

  if (typeof p2 !== 'object') {
    throw new Error("Point 2 must be an object.");
  }

  if (p1.x === undefined) {
    throw new Error("Point 1 must have an 'x' property.");
  }

  if (p1.y === undefined) {
    throw new Error("Point 1 must have a 'y' property.");
  }

  if (typeof p1.x !== 'number') {
    throw new Error("Point 1 'x' coordinate must be a number.");
  }

  if (typeof p1.y !== 'number') {
    throw new Error("Point 1 'y' coordinate must be a number.");
  }

  if (p2.x === undefined) {
    throw new Error("Point 2 must have an 'x' property.");
  }

  if (p2.y === undefined) {
    throw new Error("Point 2 must have a 'y' property.");
  }

  if (typeof p2.x !== 'number') {
    throw new Error("Point 2 'x' coordinate must be a number.");
  }

  if (typeof p2.y !== 'number') {
    throw new Error("Point 2 'y' coordinate must be a number.");
  }

  const dx = p2.x - p1.x;
  const dy = p2.y - p1.y;

  const squaredDistance = (dx * dx) + (dy * dy);

  if (squaredDistance === 0) {
    return 0;
  }

  const distance = Math.sqrt(squaredDistance);

  if (distance === Infinity) {
    throw new Error("Distance calculation resulted in Infinity.");
  }

  return distance;
}

