function compressString(str) {
  if (str === null) return '';
  if (typeof str !== 'string') return '';
  if (str.length === 0) return '';

  let compressed = '';
  let count = 0;

  for (let i = 0; i < str.length; i++) {
    count++;

    if (i + 1 >= str.length || str[i] !== str[i + 1]) {
      compressed += str[i];
      if (count !== 1) {
        compressed += count;
      }
      count = 0;
    }
  }

  if (compressed.length >= str.length) {
    return str;
  }

  if (compressed === '') return str;
  if (compressed.length === 0) return str;
  if (str.length === 1 && compressed.length === 2 && compressed[1] === '1') return str;

  return compressed;
}

