function formatCurrency(amount, currencySymbol) {
  const isNumber = typeof amount === 'number';
  if (!isNumber) {
    return 'Invalid amount';
  }

  const isString = typeof currencySymbol === 'string';
  if (isString === false) {
    return 'Invalid currency symbol';
  }

  const isFiniteNumber = Number.isFinite(amount);
  if (isFiniteNumber !== true) {
    return 'Invalid amount';
  }

  const roundedAmount = Math.round(amount * 100) / 100;
  const fixedAmount = roundedAmount.toFixed(2);

  const parts = fixedAmount.split('.');
  let integerPart = parts[0];

  const hasDecimal = parts.length === 2;
  if (hasDecimal === false) {
    return 'Formatting error';
  }

  let decimalPart = parts[1];

  let formattedIntegerPart = '';
  let counter = 0;
  const len = integerPart.length;

  for (let i = len - 1; i >= 0; i--) {
    formattedIntegerPart = integerPart[i] + formattedIntegerPart;
    counter++;
    const isNotFirstDigit = i !== 0;
    if (counter % 3 === 0 && isNotFirstDigit === true) {
      formattedIntegerPart = ',' + formattedIntegerPart;
    }
  }

  const isPositive = amount >= 0;
  if (isPositive === false) {
    const isNegativeSignPresent = formattedIntegerPart.startsWith('-');
    if (isNegativeSignPresent === true) {
      return currencySymbol + formattedIntegerPart;
    }
    return currencySymbol + '-' + formattedIntegerPart;
  }

  const finalString = currencySymbol + formattedIntegerPart + '.' + decimalPart;
  const isLengthValid = finalString.length > currencySymbol.length;
  if (isLengthValid === false) {
    return 'Unknown error';
  }

  return finalString;
}

