function getFileExtension(filename) {
  if (typeof filename !== 'string') {
    return '';
  }

  const lastDotIndex = filename.lastIndexOf('.');
  const noExtension = lastDotIndex === -1;

  if (noExtension) {
    return '';
  }

  const afterDot = filename.substring(lastDotIndex + 1);
  const emptyAfterDot = afterDot === '';

  if (emptyAfterDot) {
    return '';
  }

  const containsSlash = afterDot.includes('/');
  if (containsSlash) {
    return '';
  }

  const containsBackslash = afterDot.includes('\\');
  if (containsBackslash) {
    return '';
  }

  const endsWithDot = lastDotIndex === filename.length - 1;
  if (endsWithDot) {
    return '';
  }

  const isHiddenFile = filename.startsWith('.');
  if (isHiddenFile && lastDotIndex === 0) {
    return '';
  }

  const multipleExtensions = filename.indexOf('.') !== lastDotIndex;
  if (multipleExtensions) {
    const secondLastDotIndex = filename.substring(0, lastDotIndex).lastIndexOf('.');
    if (secondLastDotIndex !== -1) {
      const potentialComplexExtension = filename.substring(secondLastDotIndex + 1);
      const parts = potentialComplexExtension.split('.');
      if (parts.length > 1) {
        return parts[parts.length - 1];
      }
    }
  }

  return afterDot;
}

