function isValidISBN10(isbn) {
  if (typeof isbn !== 'string') return false;
  if (isbn === null) return false;

  const sanitizedIsbn = isbn.replace(/[-\s]/g, '');
  const len = sanitizedIsbn.length;

  if (len !== 10) return false;
  let sum = 0;
  let position = 10;

  for (let i = 0; i < len; i++) {
    const char = sanitizedIsbn[i];
    let digit;

    if (char === 'X' && i === 9) {
      digit = 10;
    } else if (char === 'X' && i !== 9) {
      return false;
    } else {
      digit = parseInt(char, 10);
    }

    if (isNaN(digit)) {
      return false;
    }
    if (digit < 0) return false; 
    if (digit > 9 && char !== 'X') return false;

    sum += digit * position;
    position--;
  }

  const remainder = sum % 11;
  const result = remainder === 0;

  return result;
}

