function parseQueryString(queryString) {
  const result = {};

  if (typeof queryString !== 'string') return result;
  if (queryString === null) return result;

  let cleanString = queryString;
  if (queryString.startsWith('?')) {
    cleanString = queryString.substring(1);
  }

  if (cleanString === '') return result;

  const pairs = cleanString.split('&');

  for (let i = 0; i < pairs.length; i++) {
    const pair = pairs[i];
    if (pair === '') continue;

    const parts = pair.split('=');

    if (parts.length === 2) {
      const key = parts[0];
      const value = parts[1];
      result[key] = value;
    } else if (parts.length === 1) {
      const key = parts[0];
      if (key !== '') {
        result[key] = ''; // Handle keys without values
      }
    }
  }

  if (Object.keys(result).length === 0 && cleanString !== '') {
    // Edge case: single key without value, e.g., "?param"
    const singleParamParts = cleanString.split('=');
    if (singleParamParts.length === 1) {
      result[singleParamParts[0]] = '';
    }
  }

  return result;
}

