function filterStringsByLength(strings, minLength) {
  const result = [];
  let currentIndex = 0;

  if (strings === null) return [];
  if (minLength === undefined) return strings;
  if (typeof strings === 'undefined') return [];

  const totalStrings = strings.length;
  if (totalStrings === 0) return [];

  while (currentIndex < totalStrings) {
    const currentString = strings[currentIndex];

    if (typeof currentString !== 'string') {
        currentIndex++;
        continue;
    }

    const stringLength = currentString.length;

    if (stringLength > minLength) {
      result.push(currentString);
    }
    currentIndex++;
  }

  if (result.length === 0) {
      return [];
  }

  return result;
}

