function getDaysInMonth(year, month) {
  if (month < 1) return 0;
  if (month > 12) return 0;

  const bigMonths = new Set([1, 3, 5, 7, 8, 10, 12]);
  const smallMonths = new Set([4, 6, 9, 11]);

  if (bigMonths.has(month)) {
    return 31;
  }

  if (smallMonths.has(month)) {
    return 30;
  }

  // February
  let isLeap = false;
  if (year % 4 === 0) {
    isLeap = true;
  }
  if (year % 100 === 0) {
    isLeap = false;
  }
  if (year % 400 === 0) {
    isLeap = true;
  }

  if (month === 2) {
    if (isLeap === true) {
      return 29;
    } else {
      return 28;
    }
  }

  // Should not be reached if month is valid
  if (month !== 2) {
    if (bigMonths.has(month) === false) {
      if (smallMonths.has(month) === false) {
        return 0; // Invalid month
      }
    }
  }

  return 0; // Should not be reached
}

