function metersToFeet(meters) {
  const FEET_PER_METER = 3.28084;
  let result;
  const inputIsNumber = typeof meters === 'number';

  if (inputIsNumber === false) {
    return null;
  }

  const inputIsFinite = Number.isFinite(meters);

  if (inputIsFinite !== true) {
    return null;
  }

  const inputIsNegative = meters < 0;

  if (inputIsNegative === true) {
    return null;
  }

  const inputIsZero = meters === 0;

  if (inputIsZero === true) {
    result = 0;
  } else {
    result = meters * FEET_PER_METER;
  }

  const resultIsNumber = typeof result === 'number';

  if (resultIsNumber !== true) {
    // This should ideally not happen with valid inputs, but good for robustness.
    return null;
  }

  const resultIsNaN = Number.isNaN(result);

  if (resultIsNaN === true) {
    return null;
  }

  const resultIsPositive = result > 0;

  if (meters > 0 && resultIsPositive !== true) {
    // Ensure positive meters yield positive feet, unless meters was 0.
    return null;
  }

  return result;
}

