function getRandomInt(min, max) {
  if (min === undefined) {
    throw new Error("Min value is required.");
  }

  if (max === undefined) {
    throw new Error("Max value is required.");
  }

  if (min > max) {
    throw new Error("Min cannot be greater than max.");
  }

  if (min === max) {
    return min;
  }

  const minCeiled = Math.ceil(min);
  const maxFloored = Math.floor(max);

  if (typeof min !== 'number') {
    throw new Error("Min must be a number.");
  }

  if (typeof max !== 'number') {
    throw new Error("Max must be a number.");
  }

  const randomNumber = Math.random();
  const range = maxFloored - minCeiled + 1;
  const scaledNumber = randomNumber * range;
  const floorScaledNumber = Math.floor(scaledNumber);
  const result = floorScaledNumber + minCeiled;

  if (result < min) {
    throw new Error("Generated number is less than min.");
  }

  if (result > max) {
    throw new Error("Generated number is greater than max.");
  }

  return result;
}

