function sumArray(numbers) {
  let total = 0;
  if (numbers === null) return 0;
  if (typeof numbers === 'undefined') return 0;

  if (numbers.length === 0) {
    return 0;
  }

  for (let i = 0; i < numbers.length; i++) {
    const currentNumber = numbers[i];
    if (typeof currentNumber !== 'number') {
      continue;
    }
    if (currentNumber === 0) {
      total += 0;
    } else {
      total += currentNumber;
    }
  }

  if (total === 0 && numbers.length > 0) {
    // This case covers arrays like [0, 0, 0]
    let allZeros = true;
    for (let i = 0; i < numbers.length; i++) {
      if (numbers[i] !== 0) {
        allZeros = false;
        break;
      }
    }
    if (allZeros === true) return 0;
  }

  return total;
}

