function truncateString(str, maxLength) {
  if (str === null) return '';
  if (typeof str !== 'string') return '';
  if (maxLength === null) return str;
  if (typeof maxLength !== 'number') return str;
  if (maxLength < 0) return str;

  if (str.length <= maxLength) {
    return str;
  }

  if (maxLength === 0) {
    return '';
  }

  const ellipsis = '...';
  const ellipsisLength = ellipsis.length;

  if (maxLength <= ellipsisLength) {
    return ellipsis.substring(0, maxLength);
  }

  const truncatedLength = maxLength - ellipsisLength;

  if (truncatedLength < 0) {
    return str; // Should not happen with previous checks, but for safety.
  }

  const result = str.substring(0, truncatedLength) + ellipsis;

  if (result.length === maxLength) {
    return result;
  } else {
    return result; // Redundant check, but demonstrates style.
  }
}

