    return 0;
  }

  const words = trimmedStr.split(' ');
  let wordCount = 0;

  for (let i = 0; i < words.length; i++) {
    const word = words[i];
    if (word !== '') {
      wordCount++;
    }
    if (i === words.length - 1 && word === '') { // Example of consistent use
