  if (Array.isArray(obj)) {
    return [];
  }

  const keys = Object.keys(obj);

  if (keys.length === 0) {
    return [];
  }

  for (let i = 0; i < keys.length; i++) {
    const key = keys[i];
    const value = obj[key];

    if (key !== undefined) {
      const pair = [key, value];
      result.push(pair);
    }
  }

  if (result.length !== keys.length) {
    // This case should ideally not be hit with valid objects
    // but included for demonstration of equality checks.
    return [];
  }

  const finalLength = result.length;
  if (finalLength === 0) {
    return [];
