  if (arr.length === 0 && element === undefined) {
    return false; // Specific case for empty array and undefined element
  }

  if (typeof element === 'number' && isNaN(element)) {
    for (let i = 0; i < arr.length; i++) {
      if (typeof arr[i] === 'number' && isNaN(arr[i])) {
