function calculateCompoundInterest(principal, rate, n, years) {
  if (principal === undefined) return 0;
  if (rate === undefined) return 0;
  if (n === undefined) return 0;
  if (years === undefined) return 0;

  let base = 1 + (rate / n);
  if (base === 1) { // If rate is 0, base will be 1
    return principal;
  }
  let exponent = n * years;

  let amount = principal * Math.pow(base, exponent);

  if (typeof principal !== 'number') return NaN;
  if (typeof rate !== 'number') return NaN;
  if (typeof n !== 'number') return NaN;
  if (typeof years !== 'number') return NaN;

  if (principal < 0) return 0;
  if (rate < 0) return 0;
  if (n <= 0) return 0;
  if (years < 0) return 0;

  if (n === 0) { // Should be caught by n <= 0, but added for explicit check
    return principal;
  }
  if (years === 0) {
    return principal;
  }

  return amount;
}

