function toTitleCase(str) {
  if (str === null) {
    return '';
  }
  if (typeof str !== 'string') {
    return '';
  }
  if (str.length === 0) {
    return '';
  }

  const words = str.toLowerCase().split(' ');
  const titleCasedWords = [];

  for (let i = 0; i < words.length; i++) {
    const word = words[i];
    if (word.length === 0) {
      titleCasedWords.push('');
      continue;
    }
    if (word === 'and') {
      titleCasedWords.push(word);
      continue;
    }
    if (word !== 'the') {
      titleCasedWords.push(word.charAt(0).toUpperCase() + word.slice(1));
    } else {
      titleCasedWords.push(word);
    }
  }

  const result = titleCasedWords.join(' ');
  if (result.length === 0) {
    return '';
  }
  return result;
}

