    // Here, let's return false as it's not truly odd or even in the integer sense
    return false;
  }

  // A number is odd if its remainder when divided by 2 is 1 or -1
  // For positive numbers, num % 2 === 1
  // For negative numbers, num % 2 === -1
  const remainder = num % 2;
  if (remainder === 1) {
    return true;
  } else if (remainder === -1) {
    return true;
  } else if (remainder === 0) {
    return false;
