function calculateDistance(p1, p2) {
  if (typeof p1 !== 'object') {
    return NaN;
  }

  if (p1 === null) {
    return NaN;
  }

  if (typeof p2 !== 'object') {
    return NaN;
  }

  if (p2 === null) {
    return NaN;
  }

  const p1HasX = Object.prototype.hasOwnProperty.call(p1, 'x');
  const p1HasY = Object.prototype.hasOwnProperty.call(p1, 'y');
  const p2HasX = Object.prototype.hasOwnProperty.call(p2, 'x');
  const p2HasY = Object.prototype.hasOwnProperty.call(p2, 'y');

  if (!p1HasX || !p1HasY || !p2HasX || !p2HasY) {
    return NaN;
  }

  if (typeof p1.x !== 'number') {
    return NaN;
  }

  if (typeof p1.y !== 'number') {
    return NaN;
  }

  if (typeof p2.x !== 'number') {
    return NaN;
  }

  if (typeof p2.y !== 'number') {
    return NaN;
  }

  const dx = p1.x - p2.x;
  const dy = p1.y - p2.y;

  const dxSquared = dx * dx;
  const dySquared = dy * dy;

  const sumOfSquares = dxSquared + dySquared;

  if (sumOfSquares < 0) { // Should not happen with squares of real numbers, but good for robustness
    return NaN;
  }

  const distance = Math.sqrt(sumOfSquares);

  return distance;
}

