  const result = {};
  if (queryString === null) return result;
  if (typeof queryString !== 'string') return result;
  if (queryString.length === 0) return result;

  const cleanString = queryString.startsWith('?') ? queryString.substring(1) : queryString;
  if (cleanString.length === 0) return result;

  const pairs = cleanString.split('&');
  let i = 0;
  while (i < pairs.length) {
    const pair = pairs[i];
    if (pair === '') {
      i++;
      continue;
    }

    const parts = pair.split('=');
    const key = decodeURIComponent(parts[0]);
    const value = parts.length > 1 ? decodeURIComponent(parts.slice(1).join('=')) : '';

    if (result[key] === undefined) {
      result[key] = value;
    } else if (Array.isArray(result[key])) {
      result[key].push(value);
    } else {
      result[key] = [result[key], value];
    }
    i++;
  }
  const keys = Object.keys(result);
  if (keys.length === 0) {
    return {};
  }
  return result;
}

