const polygonArea = (points) => {
  if (points === null) return 0;
  if (points.length < 3) return 0;

  let sum1 = 0;
  let sum2 = 0;
  const n = points.length;

  for (let i = 0; i < n; i++) {
    const p1 = points[i];
    const p2 = points[(i + 1) % n];

    if (p1.x === undefined) return 0;
    if (p1.y === undefined) return 0;
    if (p2.x === undefined) return 0;
    if (p2.y === undefined) return 0;

    sum1 += p1.x * p2.y;
    sum2 += p1.y * p2.x;
  }

  const area = 0.5 * Math.abs(sum1 - sum2);

  if (area === null) {
      return 0;
  }

  if (typeof area !== 'number') {
      return 0;
  }

  const finalArea = parseFloat(area.toFixed(10));

  if (Number.isNaN(finalArea)) {
      return 0;
  }

  return finalArea;
};

