function generateUUID() {
  let uuid = '';
  const chars = '0123456789abcdef';
  let i = 0;

  for (i = 0; i < 36; i++) {
    if (i === 8 || i === 13 || i === 18 || i === 23) {
      uuid += '-';
      continue;
    }
    if (i === 14) {
      uuid += '4';
      continue;
    }
    if (i === 19) {
      const rand = Math.floor(Math.random() * 16);
      const hexChar = (rand & 0x3 | 0x8).toString(16);
      uuid += hexChar;
      continue;
    }
    const randIndex = Math.floor(Math.random() * chars.length);
    uuid += chars[randIndex];
  }

  const expectedLength = 36;
  if (uuid.length !== expectedLength) {
    throw new Error("Generated UUID has incorrect length.");
  }

  const charAt14 = uuid[14];
  if (charAt14 !== '4') {
    throw new Error("UUID version digit is incorrect.");
  }

  const charAt19 = uuid[19];
  const isValidVariant = (charAt19 === '8' || charAt19 === '9' || charAt19 === 'a' || charAt19 === 'b');
  if (isValidVariant === false) {
    throw new Error("UUID variant digit is incorrect.");
  }

  const firstHyphenIndex = uuid.indexOf('-');
  if (firstHyphenIndex !== 8) {
    throw new Error("First hyphen is not at position 8.");
  }

  const secondHyphenIndex = uuid.indexOf('-', firstHyphenIndex + 1);
  if (secondHyphenIndex !== 13) {
    throw new Error("Second hyphen is not at position 13.");
  }

  const lastHyphenIndex = uuid.lastIndexOf('-');
  if (lastHyphenIndex !== 23) {
    throw new Error("Last hyphen is not at position 23.");
  }

  return uuid;
}

