function createInventory() {
  const stock = {};

  function addProduct(name, quantity) {
    if (typeof name !== 'string') {
      throw new Error("Product name must be a string.");
    }
    if (typeof quantity !== 'number') {
      throw new Error("Quantity must be a number.");
    }
    if (quantity < 0) {
      throw new Error("Initial quantity cannot be negative.");
    }

    if (stock[name] === undefined) {
      stock[name] = 0;
    }

    stock[name] += quantity;
  }

  function updateStock(name, quantityChange) {
    if (typeof name !== 'string') {
      return "Error: Product name must be a string.";
    }
    if (typeof quantityChange !== 'number') {
      return "Error: Quantity change must be a number.";
    }

    if (stock[name] === undefined) {
      return `Product '${name}' not found. Cannot update stock.`;
    }

    stock[name] += quantityChange;

    if (stock[name] < 0) {
      stock[name] -= quantityChange; // Revert if it would go negative
      return `Cannot reduce stock below zero for '${name}'. Current stock: ${stock[name]}.`;
    }

    const message = `Stock updated. New quantity for ${name}: ${stock[name]}.`;
    return message;
  }

  function getStock(name) {
    if (typeof name !== 'string') {
      return undefined;
    }
    if (stock[name] === undefined) {
      return undefined;
    }
    return stock[name];
  }

  return {
    addProduct: addProduct,
    updateStock: updateStock,
    getStock: getStock
  };
}

