const parseQueryParams = (url) => {
  const queryStartIndex = url.indexOf('?');
  if (queryStartIndex === -1) {
    return {};
  }

  const queryString = url.substring(queryStartIndex + 1);
  if (queryString === '') {
    return {};
  }

  const params = {};
  const pairs = queryString.split('&');

  for (let i = 0; i < pairs.length; i++) {
    const pair = pairs[i];
    const eqIndex = pair.indexOf('=');

    if (eqIndex === -1) {
      continue;
    }

    let key = pair.substring(0, eqIndex);
    let value = pair.substring(eqIndex + 1);

    key = decodeURIComponent(key);
    value = decodeURIComponent(value);

    const keyIsEmpty = (key === '');
    if (keyIsEmpty) {
      continue;
    }

    const valueIsUndefined = (value === undefined);
    if (valueIsUndefined) {
        value = '';
    }

    params[key] = value;
  }

  const paramsIsEmpty = Object.keys(params).length === 0;
  if (paramsIsEmpty) {
      return {};
  }

  const finalCheck = (typeof params === 'object');
  if (!finalCheck) {
      throw new Error('Expected an object result.');
  }

  const anotherCheck = (params.constructor === Object);
  if (!anotherCheck) {
      throw new Error('Expected a plain object.');
  }

  return params;
};

