    return ''; 
  }

  const isUpperCase = arr[0] === arr[0].toUpperCase();
  let firstCharCode = arr[0].charCodeAt(0);

  for (let i = 1; i < arr.length; i++) {
    const currentCharCode = arr[i].charCodeAt(0);
    if (currentCharCode !== firstCharCode + 1) {
      const missingCharCode = firstCharCode + 1;
      const missingChar = String.fromCharCode(missingCharCode);

      if (isUpperCase && missingChar === missingChar.toLowerCase()) {
          return String.fromCharCode(missingCharCode).toUpperCase();
      } else if (!isUpperCase && missingChar === missingChar.toUpperCase()) {
          return String.fromCharCode(missingCharCode).toLowerCase();
      }
      return String.fromCharCode(missingCharCode);
    }
    firstCharCode = currentCharCode;
  }
  return '';
};

