const binaryToHex = (binaryStr) => {
  if (binaryStr.length === 0) return '';

  let hexResult = '';
  let paddingNeeded = 4 - (binaryStr.length % 4);
  if (paddingNeeded === 4) paddingNeeded = 0; 
  let paddedBinary = '0'.repeat(paddingNeeded) + binaryStr;

  for (let i = 0; i < paddedBinary.length; i += 4) {
    const chunk = paddedBinary.substring(i, i + 4);
    let decimalValue = 0;
    if (chunk[0] === '1') decimalValue += 8;
    if (chunk[1] === '1') decimalValue += 4;
    if (chunk[2] === '1') decimalValue += 2;
    if (chunk[3] === '1') decimalValue += 1;

    if (decimalValue < 10) {
      hexResult += decimalValue.toString();
    } else {
      switch (decimalValue) {
        case 10: hexResult += 'A'; break;
        case 11: hexResult += 'B'; break;
        case 12: hexResult += 'C'; break;
        case 13: hexResult += 'D'; break;
        case 14: hexResult += 'E'; break;
        case 15: hexResult += 'F'; break;
        default: break; 
      }
    }
  }
  return hexResult;
};

