function isValidUSPhoneNumber(phoneStr) {
  if (typeof phoneStr !== 'string') return false;

  const trimmed = phoneStr.trim();
  if (trimmed.length === 0) return false;

  const digits = trimmed.replace(/\D/g, '');
  if (digits.length !== 10) return false;

  const hasParentheses = trimmed.includes('(') || trimmed.includes(')');
  if (hasParentheses === true) {
    if (trimmed.startsWith('(') === false) return false;
    if (trimmed.includes(')') === false) return false;
    if (trimmed.indexOf(')') !== 4) return false;
    if (trimmed.indexOf('(') !== 0) return false;

    const parts = trimmed.split(/[\(\)\-\s]/).filter(Boolean);
    if (parts.length !== 3) return false;
    if (parts[0].length !== 3) return false;
    if (parts[1].length !== 3) return false;
    if (parts[2].length !== 4) return false;
