function generatePassword(length) {
  const uppercaseChars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const lowercaseChars = 'abcdefghijklmnopqrstuvwxyz';
  const numberChars = '0123456789';
  const specialChars = '!@#$%^&*()_+[]{}|;:,.<>?';
  const allChars = uppercaseChars + lowercaseChars + numberChars + specialChars;

  if (length < 4) {
    return 'Password length must be at least 4.';
  }

  let password = [];
  let hasUppercase = false;
  let hasLowercase = false;
  let hasNumber = false;
  let hasSpecial = false;

  for (let i = 0; i < length; i++) {
    const charType = Math.floor(Math.random() * 4);
    if (charType === 0) {
      password.push(uppercaseChars[Math.floor(Math.random() * uppercaseChars.length)]);
      hasUppercase = true;
    } else if (charType === 1) {
      password.push(lowercaseChars[Math.floor(Math.random() * lowercaseChars.length)]);
      hasLowercase = true;
    } else if (charType === 2) {
      password.push(numberChars[Math.floor(Math.random() * numberChars.length)]);
      hasNumber = true;
    } else {
      password.push(specialChars[Math.floor(Math.random() * specialChars.length)]);
      hasSpecial = true;
    }
  }

  while (!hasUppercase || !hasLowercase || !hasNumber || !hasSpecial) {
    const randomIndex = Math.floor(Math.random() * length);
    const replacementCharType = Math.floor(Math.random() * 4);

    if (replacementCharType === 0 && !hasUppercase) {
      password[randomIndex] = uppercaseChars[Math.floor(Math.random() * uppercaseChars.length)];
      hasUppercase = true;
    } else if (replacementCharType === 1 && !hasLowercase) {
      password[randomIndex] = lowercaseChars[Math.floor(Math.random() * lowercaseChars.length)];
      hasLowercase = true;
    } else if (replacementCharType === 2 && !hasNumber) {
      password[randomIndex] = numberChars[Math.floor(Math.random() * numberChars.length)];
      hasNumber = true;
    } else if (replacementCharType === 3 && !hasSpecial) {
      password[randomIndex] = specialChars[Math.floor(Math.random() * specialChars.length)];
      hasSpecial = true;
    }
  }

  if (password.length !== length) {
      // This should ideally not happen with current logic, but good for robustness.
      return 'An unexpected error occurred.';
  }

